    def test_terminals_page_git_sidebar_freezes_its_scope_header(self):
        """Repository, branch and scope stay on screen; Publish scrolls away.

        Which repository and which part of it is what every change row and
        every commit below is read against, so the repo bar is sticky. Publish
        is the one action here that reaches a remote and is deliberately not
        frozen with it -- it moved into its own section immediately below.
        """
        sidebar = self._static("js/explorer-git-sidebar.js")
        css = self._static("css/terminals.css")

        # The button is no longer inside the frozen header: the repo bar's
        # section is closed before the publish section opens.
        bar_at = sidebar.index("explorer-diff-sidebar-section explorer-git-repo-bar")
        publish_box_at = sidebar.index("explorer-git-publish-box", bar_at)
        publish_at = sidebar.index("data-explorer-git-publish", bar_at)
        self.assertNotIn("data-explorer-git-publish", sidebar[bar_at:publish_box_at])
        self.assertLess(publish_box_at, publish_at)

        repo_bar_css = css[css.index(".explorer-git-repo-bar {"):]
        repo_bar_css = repo_bar_css[: repo_bar_css.index("}")]
        self.assertIn("position: sticky;", repo_bar_css)
        self.assertIn("top: 0;", repo_bar_css)
        # A sticky box is painted over what slides beneath it, so it needs an
        # opaque background of its own -- from a token, never a literal.
        self.assertIn("background: var(--explorer-bar-bg);", repo_bar_css)
        self.assertNotRegex(repo_bar_css, r":\s*#[0-9a-fA-F]{3,6}\b")

        # The Graph's commit find is sticky too and stacks *below* the frozen
        # header rather than behind it, on a height the panel publishes.
        search_css = css[css.index(".explorer-git-commit-search {"):]
        search_css = search_css[: search_css.index("}")]
        self.assertIn("top: var(--explorer-git-header-height, 0px);", search_css)
        self.assertIn("--explorer-git-header-height", sidebar)
        self.assertIn("function observeExplorerGitHeaderHeight(index)", sidebar)

    def test_terminals_page_files_tree_marks_the_pin_and_the_follow(self):
        """Both Git scopes are reported on the row they are on.

        Follow is a mode with no fixed path of its own, so a pressed button in
        a sidebar the reader may not have open was the only thing saying it was
        on at all. The chain now sits on the row it is tracking, beside the pin
        marker and sharing its rule rather than restating the box.
        """
        tree = self._static("js/explorer-tree.js")
        sidebar = self._static("js/explorer-git-sidebar.js")
        css = self._static("css/terminals.css")

        # The markup hooks the CSS and the paint both key on.
        self.assertIn('class="explorer-tree-follow-mark"', tree)
        self.assertIn("data-explorer-tree-follow-root", tree)
        self.assertIn("Git scope follows this row", tree)
        self.assertIn("EXPLORER_GIT_FOLLOW_ICON", tree)

        # One rule for both markers, so they cannot drift out of alignment
        # with each other or with the row controls beside them (guardrail 7).
        self.assertIn(
            ".explorer-tree-pin-mark,\n        .explorer-tree-follow-mark {", css
        )
        self.assertIn(
            ".explorer-tree-pin-mark[hidden],\n        .explorer-tree-follow-mark[hidden] {",
            css,
        )

        # Both markers move on the one cross-surface paint, and a Follow
        # toggle reaches it before the repository round trip it also starts.
        self.assertIn("function refreshExplorerGitScopeAffordances(index)", sidebar)
        self.assertIn("applyExplorerTreeScopeMarks(index);", sidebar)
        toggle = sidebar[sidebar.index("async function toggleExplorerGitFollowBrowsing(index)"):]
        toggle = toggle[: toggle.index("\n    /*")]
        self.assertLess(
            toggle.index("refreshExplorerGitScopeAffordances(index);"),
            toggle.index("await loadExplorerGitRepo(index);"),
        )

    def test_terminals_page_vendors_highlightjs_source_highlighting(self):
        """The Source viewer highlights
        the whole document once with the pinned Highlight.js build and keeps the
        handwritten lexer as a fallback."""
        response = self.client.get("/terminals")

        self.assertEqual(response.status_code, 200)
        html = self._page_html(response)
        # Assets are vendored and loaded locally, never from a CDN.
        self.assertIn("/static/vendor/highlight.min.js", html)
        self.assertNotIn("cdnjs.cloudflare.com", html)
        # Explicit grammar map (no auto-detection) and whole-document tokenizer.
        self.assertIn("const EXPLORER_HLJS_LANGUAGE = Object.freeze({", html)
        self.assertIn("function explorerHighlightDocumentLines(content, normalizedLanguage)", html)
        self.assertIn("function explorerRenderHighlightedRuns(runs, searchRanges = [])", html)
        # Grammar is always passed explicitly; auto-detection is never used.
        self.assertNotIn("hljs.highlightAuto(", html)
        # The whole-document pass hands Highlight.js markup to the worker
        # core's own parser, never to template.innerHTML: the HTML parser
        # normalizes CRLF to LF, which put every run offset one character per
        # line away from the source the search marks are measured against.
        # tests/test_explorer_source_frame.py executes that on a CRLF buffer.
        self.assertIn("core.highlightToCompact(", html)
        # Source rendering prefers the whole-document pass, falling back per line.
        self.assertIn(": explorerHighlightDocumentLines(content, normalizedLanguage);", html)
        # Which of those two a row gets — the cached token map or the per-line
        # fallback — is executed rather than spelled out here:
        # tests/test_explorer_source_frame.py renders with and without a token
        # map and with a failed highlight job.
        #
        # Non-trivial buffers start as plain escaped rows while the shared,
        # bounded worker pool tokenizes; the transferred result is compact
        # (typed arrays and a class dictionary, never a cloned Map of run
        # objects), which tests/test_explorer_workers.py round-trips. The
        # threshold below is the one part with no executable seam — it is a
        # documented number, so the named constant stays.
        self.assertIn("/static/js/explorer-worker-client.js", html)
        self.assertIn("HIGHLIGHT_WORKER_MIN_CHARS = 64 * 1024", html)
        # The oversized-file guard is preserved for the highlighter.
        self.assertIn("if (source.length > EXPLORER_PLAIN_PREVIEW_THRESHOLD) {", html)
        # Explorer-scoped token palette for both themes, shared by the Source
        # view and the Diff2Html host so diff code keeps its syntax colours.
        self.assertIn(
            ":is(.explorer-source-line-code, .explorer-diff2html) .hljs-keyword,",
            html,
        )
        self.assertIn(
            '.explorer-pane[data-explorer-theme="dark"] '
            ":is(.explorer-source-line-code, .explorer-diff2html) .hljs-string,",
            html,
        )

    def test_terminals_page_vendors_diff2html_precise_diffs(self):
        """Diffs render through the
        pinned Diff2Html build with intraline emphasis, surface truncation, and
        keep the tolerant side-by-side renderer as a fallback."""
        response = self.client.get("/terminals")

        self.assertEqual(response.status_code, 200)
        html = self._page_html(response)
        self.assertIn("/static/vendor/diff2html-ui-base.min.js", html)
        self.assertIn("/static/vendor/diff2html.min.css", html)
        # Diff2Html configuration: char-level intraline + explicit limits.
        self.assertIn("function explorerDiff2HtmlConfig(tier)", html)
        self.assertIn("matching: 'words',", html)
        self.assertIn("diffStyle: 'char',", html)
        self.assertIn("synchronisedScroll: false,", html)
        self.assertIn("matchingMaxComparisons: 1500,", html)
        # Lines past this length lose intraline emphasis entirely, so the cap
        # tracks Diff2Html's own default rather than sitting below it.
        self.assertIn("maxLineLengthHighlight: 10000", html)
        self.assertIn(
            "new window.Diff2HtmlUI(host, diff, explorerDiff2HtmlConfig(tier), window.hljs)",
            html,
        )
        # draw() highlights on its own because the config sets `highlight: true`.
        # A second highlightCode() pass nests a duplicate hljs span inside every
        # span the first pass produced, so there must be exactly one draw call
        # and no explicit re-highlight.
        self.assertIn("ui.draw();", html)
        self.assertNotIn("ui.highlightCode();", html)
        # Diff2Html remains synchronous for small/medium patches, falling back
        # to the handwritten side-by-side renderer on the page when it is
        # unavailable. The large tier's parse goes through the shared worker
        # and only its DOM adapter stays here, preserving both undo
        # affordances. Both branches are driven end to end rather than read out
        # of this file — tests/test_explorer_workers.py for the worker path and
        # the missing-core degradation, and DiffRepaintTestCase in
        # tests/test_explorer_repaint.py for the synchronous fallback render.
        self.assertIn("function renderExplorerSideBySideDiff(index, diff)", html)
        # Truncation is captured from the API and surfaced without blocking.
        self.assertIn("pane._explorerDiffTruncated = Boolean(data.truncated);", html)
        self.assertIn("function explorerDiffTruncationBannerHtml(pane)", html)
        self.assertIn("Diff truncated to 256 KiB / 4,000 lines", html)
        self.assertIn(".explorer-diff-truncated {", html)
        # The diff host inherits the per-tab editor zoom.
        self.assertIn(".explorer-diff2html {", html)
        self.assertIn("font-size: var(--explorer-editor-font-size, .78rem);", html)
        self.assertIn(
            ".explorer-diff2html .d2h-diff-table {\n"
            "            font-size: inherit;",
            html,
        )
        # Original source lines remain unwrapped in two fixed, equal-width
        # panes. A sticky scrollbar controls each side independently.
        self.assertIn(
            ".explorer-diff2html .d2h-code-side-line {\n"
            "            box-sizing: border-box;\n"
            "            width: 100%;\n"
            "            padding: 0 .5em;\n"
            "            white-space: nowrap;",
            html,
        )
        self.assertIn(
            ".explorer-diff2html .d2h-code-line-ctn {\n"
            "            white-space: pre;",
            html,
        )
        self.assertIn("width: 50%;", html)
        self.assertIn("flex: 1 1 50%;", html)
        self.assertIn(
            ".explorer-diff2html .d2h-code-side-linenumber {\n"
            "            position: sticky;\n"
            "            z-index: 2;\n"
            "            left: 0;",
            html,
        )
        # ...and the code cell claims the table's excess width. Auto layout
        # otherwise hands a share of that excess to the number column whenever
        # the code content is narrower than the side (one- or two-word lines);
        # the number cell's own max-width then holds its box at 4em and the
        # rest of that column paints as a blank gap in front of every code
        # line, differently on each side since each side is its own table
        # (docs/images/huge_diff_indent.PNG).
        self.assertIn(
            ".explorer-diff2html .d2h-diff-table td + td {\n"
            "            width: 100%;",
            html,
        )
        self.assertIn("padding: 0 .5em;", html)
        self.assertIn(".explorer-diff-horizontal-scrollbars {", html)
        self.assertIn("position: sticky;", html)
        self.assertIn("function synchroniseExplorerDiffScrollbars(host)", html)
        self.assertIn("function observeExplorerDiffLayout(host)", html)
        self.assertIn("track.dataset.explorerDiffSide = sideIndex === 0 ? 'left' : 'right';", html)
        self.assertIn("side.scrollLeft = track.scrollLeft;", html)
        self.assertIn("observeExplorerDiffLayout(host);", html)

    def test_richer_source_and_diff_vendored_assets_are_served(self):
        """Phase 1/2 assets are served locally and pinned (highlight.js custom
        build includes the extra grammars beyond the common bundle)."""
        for filename in (
            "vendor/highlight.min.js",
            "vendor/diff2html-ui-base.min.js",
            "vendor/diff2html.min.css",
            "js/explorer-worker-core.js",
            "js/explorer-worker-client.js",
            "js/explorer-worker.js",
        ):
            with self.subTest(filename=filename):
                response = self.client.get(f"/static/{filename}")
                self.assertEqual(response.status_code, 200)
                self.assertGreater(len(response.get_data()), 1000)
                response.close()
        highlight = self.client.get("/static/vendor/highlight.min.js")
        highlight_body = highlight.get_data(as_text=True)
        highlight.close()
        for grammar in ("powershell", "dockerfile"):
            with self.subTest(grammar=grammar):
                self.assertIn(grammar, highlight_body)

