    def test_tree_open_tab_button_opens_the_tab_in_the_background(self):
        """The tree row open-in-new-tab control queues a tab without stealing the viewer's focus.

        Opening three files in a row must leave the reader on the file they
        were already looking at, so the opener only touches the tab strip.
        """
        tree = self._static("js/explorer-tree.js")
        tabs = self._static("js/explorer-tabs.js")
        opener = tabs[
            tabs.index("function openExplorerFileInBackgroundTab(index, path,"):
            tabs.index("function ensureExplorerTabLineWrap(tab)")
        ]
        # No focus change, no viewer repaint, and no fetch — activateExplorerTab
        # loads the file lazily when the tab is first clicked.
        self.assertNotIn("_explorerActiveTabId =", opener)
        self.assertNotIn("_explorerRenderedTabId", opener)
        self.assertNotIn("openExplorerFile(", opener)
        self.assertNotIn("fetch(", opener)
        # The tab still joins the strip and the persisted session snapshot.
        self.assertIn("explorerEnsurePinnedTab(pane, path)", opener)
        self.assertIn("renderExplorerTabStrip(index);", opener)
        self.assertIn("persistExplorerTabsToSession(index);", opener)
        # The open-in-new-tab handler routes there and carries the row's Git badge along.
        self.assertIn(
            "git: explorerTreeEntryForPath(terminals[index], path)?.git || null",
            tree,
        )

    def test_reopening_an_already_open_tab_flashes_it_instead_of_focusing(self):
        """Open-in-new-tab on a file that already has a tab answers without moving the viewer."""
        tabs = self._static("js/explorer-tabs.js")
        opener = tabs[
            tabs.index("function openExplorerFileInBackgroundTab(index, path,"):
            tabs.index("function ensureExplorerTabLineWrap(tab)")
        ]
        # The already-open case is decided before the tab is ensured, then
        # flashed after the strip is rebuilt so the class lands on live DOM.
        self.assertIn("const alreadyOpen = Boolean(key) && ensureExplorerTabState(pane)", opener)
        self.assertLess(
            opener.index("renderExplorerTabStrip(index);"),
            opener.index("flashExplorerTab(index, pinnedTab.id);"),
        )
        # It still does not activate the tab — the flash replaces focus.
        self.assertNotIn("activateExplorerTab", opener)
        flash = tabs[
            tabs.index("function flashExplorerTab(index, id)"):
            tabs.index("function openExplorerFileInBackgroundTab(index, path,")
        ]
        # A tab id is a file path, so it is matched by dataset rather than
        # interpolated into a CSS selector.
        self.assertNotIn("querySelector(`[data-explorer-tab=", flash)
        self.assertIn("entry.dataset.explorerTab || '') === id", flash)
        # The pulse self-clears, like the locate-in-tree flash it mirrors.
        self.assertIn("tabEl.classList.add('explorer-tab-located');", flash)
        self.assertIn(
            "window.setTimeout(() => tabEl.classList.remove('explorer-tab-located'), 1200);",
            flash,
        )
        # Token-driven styling, no palette literals.
        css = self._static("css/terminals.css")
        self.assertIn(".explorer-tab.explorer-tab-located {", css)
        located = css[css.index(".explorer-tab.explorer-tab-located {"):]
        located = located[: located.index("}")]
        self.assertIn("var(--t-accent)", located)
        self.assertNotIn("#", located)

    def test_preview_double_click_pins_in_the_background(self):
        """Double-clicking Preview bookmarks its file; the viewer does not jump."""
        tabs = self._static("js/explorer-tabs.js")
        promote = tabs[
            tabs.index("function promoteExplorerPreviewTab(index)"):
            tabs.index("function revealExplorerTabInTree(index, id)")
        ]
        # Focus is untouched: the non-focusing helper is used, the rendered-tab
        # stamp stays on Preview (whose DOM is still what the viewer shows),
        # and an existing tab for the path flashes instead of being activated.
        self.assertIn("explorerEnsurePinnedTab(pane, path)", promote)
        self.assertNotIn("explorerAssignOpenTab", promote)
        self.assertNotIn("_explorerActiveTabId =", promote)
        self.assertNotIn("_explorerRenderedTabId =", promote)
        self.assertIn("flashExplorerTab(index, existing.id);", promote)
        self.assertNotIn("activateExplorerTab(index", promote)
        # The carried per-tab state still rides along, so the first click on
        # the new tab restores the mode/scroll/zoom Preview had.
        for carried in (
            "pinnedTab.git = preview.git || null;",
            "pinnedTab.view = { ...preview.view };",
            "pinnedTab.fontSize = preview.fontSize;",
            "pinnedTab.lineWrap = { ...preview.lineWrap };",
            "pinnedTab.preferredMode = preview.preferredMode;",
        ):
            self.assertIn(carried, promote)
        # Still refuses to pin a directory listing or a half-loaded viewer.
        self.assertIn("pane._explorerMode !== 'file'", promote)
        self.assertIn("pane._explorerRenderedTabId !== EXPLORER_PREVIEW_TAB_ID", promote)

    def test_closing_the_active_tab_falls_back_to_preview(self):
        """Closing the tab you are reading lands on Preview, not the neighbour."""
        tabs = self._static("js/explorer-tabs.js")
        close = tabs[
            tabs.index("async function closeExplorerTab(index, id)"):
            tabs.index("function explorerPersistableTabView(tab)")
        ]
        # No positional neighbour lookup survives.
        self.assertNotIn("position - 1", close)
        self.assertIn("pane._explorerActiveTabId = EXPLORER_PREVIEW_TAB_ID;", close)
        # Rendered directly rather than through activateExplorerTab, whose
        # already-shown guard would short-circuit in the one state where the
        # viewer holds Preview while a pinned tab is active, stranding the
        # closed tab in the strip.
        self.assertNotIn("activateExplorerTab(index", close)
        self.assertIn("renderExplorerActiveTab(index);", close)
        # Both paths (active and background close) update the strip and the
        # persisted tab set exactly once.
        self.assertEqual(close.count("renderExplorerTabStrip(index);"), 1)
        self.assertEqual(close.count("persistExplorerTabsToSession(index);"), 1)
        # The permanent Preview tab is still not closable, and a dirty edit in
        # the closed tab is still confirmed before anything is discarded.
        self.assertIn("if (!pane || id === EXPLORER_PREVIEW_TAB_ID) {", close)
        self.assertIn("confirmDiscardExplorerEdit(index, 'Closing this tab')", close)

